class Box {
    int value;

    Box(int v) {
        value = v;
    }
}

public class Main {
    public static void main(String[] args) {
        Box a = new Box(3);
        Box b = new Box(7);
        a.value = b.value + 1;
        System.out.println(a.value + " " + b.value);
    }
}

class Wallet {
    int money;
}

public class Main {
    static void spend(Wallet w) {
        w.money = w.money - 20;
    }

    public static void main(String[] args) {
        Wallet mine = new Wallet();
        mine.money = 50;
        spend(mine);
        System.out.println(mine.money);
    }
}

class Student {
    private String name;
    private int marks;

    Student(String name, int marks) {
        this.name = name;
        this.marks = marks;
    }

    String report() {
        return name + ": " + marks;
    }
}

public class Main {
    public static void main(String[] args) {
        Student s = new Student("Ravi", 72);
        System.out.println(s.report());
    }
}
